private func nativeBuiltinConstant<T: GodotValue & ~Copyable>(_ type: GDExtensionVariantType, _ name: String, as target: T.Type) -> T {
    let value = GodotVariant(initializing: { api.variant_get_constant_value!(type, makeName(name), $0) })
    return try! value.withStorage { try T.decodeVariant($0) }
}
